<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;numObj.toPrecision(1) is &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#24292E;"> numObj.</span><span style="color:#6F42C1;">toPrecision</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">)); </span><span style="color:#6A737D;">//输出 5</span></span>
